const double = (x) => x * 2;
const increment = (x) => x + 1;
console.log(typeof double);
const fns = [double, increment];
console.log(fns[0](5), fns[1](5));

function applyTwice(fn, x) {
  return fn(fn(x));
}
const double = (x) => x * 2;
console.log(applyTwice(double, 3));

function multiplier(n) {
  return (x) => x * n;
}
const triple = multiplier(3);
console.log(triple(5));
console.log(typeof multiplier(3));

const nums = [1, 2, 3, 4];
console.log(nums.map((n) => n * 2).join());
console.log(nums.filter((n) => n % 2 === 0).join());
console.log(nums.reduce((sum, n) => sum + n, 0));
console.log(nums.join());

const hello = () => console.log("hi");
const run = (callback) => callback();
run(hello);
